INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(7788, 'koKR', 'Pokonaj najeźdźców!', 'Za tym tunelem znajdziesz pole walki i zamętu, $N. Horda wciąż pustoszy nasz święty las, wycinając wiecznie zielone drzewa, by napędzać swoje machiny wojenne.$B$BWejdź do Wąwozu Wojennej Pieśni i broń Warowni Srebrnego Skrzydła. Odeprzyj najeźdźców z Hordy!$B$BZrób to, a zdobędziesz talizman zasługi. Przynieś mi taki talizman, $N, a cię wynagrodzę.', 'Wejdź do Wąwozu Wojennej Pieśni i pokonaj Hordę, zdobądź Odznakę honoru Wąwozu Wojennej Pieśni i wróć do strażniczki Dalekiej Pieśni w Gaju Srebrnego Skrzydła.', '', 'Wróć do strażniczki Dalekiej Pieśni nad Jeziorem Upadłego Nieba w Jesionowej Kniei.', '', '', '', '', 0),
(7789, 'koKR', 'Zdław uzurpatorów ze Srebrnego Skrzydła', 'Dzikie ostępy Jesionowej Kniei ulegną potędze Hordy. Nic, co mówi czy robi Srebrne Skrzydło, nie powstrzyma naszej suwerennej woli. Kalimdor należy do Hordy. Jak śmią próbować przeszkodzić nam w zbieraniu tego, co nam się słusznie należy!$B$BNiech duma rozpiera twoją pierś, gdy będziesz udaremniać ich marne próby spowolnienia naszego pochodu. Zniszcz Strażniczki Srebrnego Skrzydła i zdobądź odznakę honoru Wojennej Pieśni. Wróć do mnie z taką odznaką, $N, a zostaniesz $gnagrodzony:nagrodzona;.$B', 'Wejdź do Wąwozu Wojennej Pieśni i pokonaj Przymierze, zdobądź Odznakę honoru Wąwozu Wojennej Pieśni i zanieś ją kapitanowi Czaszkotłukowi w Obozie Mor\'shan.', '', 'Wróć do kapitana Czaszkotłuka w Obozie Mor\'shan na Pustkowiach.', '', '', '', '', 0),
(7871, 'koKR', 'Pokonaj najeźdźców!', 'Za tym tunelem znajdziesz pole walki i zamętu, $N. Horda wciąż pustoszy nasz święty las, wycinając wiecznie zielone drzewa, by napędzać swoje machiny wojenne.$B$BWejdź do Wąwozu Wojennej Pieśni i broń Warowni Srebrnego Skrzydła. Odeprzyj najeźdźców z Hordy!$B$BZrób to, a zdobędziesz talizman zasługi. Przynieś mi taki talizman, $N, a cię wynagrodzę.', 'Wejdź do Wąwozu Wojennej Pieśni i pokonaj Hordę, zdobądź Odznakę honoru Wąwozu Wojennej Pieśni i wróć do strażniczki Dalekiej Pieśni w Gaju Srebrnego Skrzydła.', '', 'Wróć do strażniczki Dalekiej Pieśni nad Jeziorem Upadłego Nieba w Jesionowej Kniei.', '', '', '', '', 0),
