INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(7789, 'koKR', '<Kapitan Czaszkotłuk ryczy triumfalnie.>$B$BIle jeszcze zdołają wytrzymać? Ilu jeszcze parszywców z Przymierza musi zginąć z ręki Hordy, zanim się wycofają? Czas pokaże...', 0),
(7874, 'koKR', '<Kapitan Czaszkotłuk ryczy triumfalnie.>$B$BIle jeszcze zdołają wytrzymać? Ilu jeszcze parszywców z Przymierza musi zginąć z ręki Hordy, zanim się wycofają? Czas pokaże.', 0),
(7875, 'koKR', '<Kapitan Czaszkotłuk ryczy triumfalnie.>$B$BIle jeszcze zdołają wytrzymać? Ilu jeszcze parszywców z Przymierza musi zginąć z ręki Hordy, zanim się wycofają? Czas pokaże.', 0),
(7876, 'koKR', '<Kapitan Czaszkotłuk ryczy triumfalnie.>$B$BIle jeszcze zdołają wytrzymać? Ilu jeszcze parszywców z Przymierza musi zginąć z ręki Hordy, zanim się wycofają? Czas pokaże.', 0),
(7886, 'koKR', 'Dziękuję ci, $N. O twoich wyczynach w Wąwozie Wojennej Pieśni mówi cała Jesionowa Knieja.', 0),
(7887, 'koKR', 'Dziękuję ci, $N. O twoich wyczynach w Wąwozie Wojennej Pieśni mówi cała Jesionowa Knieja.', 0),
