(7922, 'koKR', 'Nocne elfy i ich sojusznicy muszą drżeć na sam szept twojego imienia! Za Hordę!', 0),
(7923, 'koKR', 'Nocne elfy i ich sojusznicy muszą drżeć na sam szept twojego imienia! Za Hordę!', 0),
(7924, 'koKR', 'Nocne elfy i ich sojusznicy muszą drżeć na sam szept twojego imienia! Za Hordę!', 0),
(7925, 'koKR', 'Nocne elfy i ich sojusznicy muszą drżeć na sam szept twojego imienia! Za Hordę!', 0),
(8266, 'koKR', 'Cóż, nie $guciekłeś:uciekłaś; w obliczu porażki. $GDotrzymałeś:Dotrzymałaś; pola, $N, a koniec końców to właśnie czyni prawdziwego bohatera. Bez wątpienia następnym razem zwyciężysz... ale tak czy inaczej dziękujemy ci za twój wysiłek.', 0),
(8267, 'koKR', 'Cóż, nie $guciekłeś:uciekłaś; w obliczu porażki. $GDotrzymałeś:Dotrzymałaś; pola, $N, a koniec końców to właśnie czyni prawdziwego bohatera. Bez wątpienia następnym razem zwyciężysz... ale tak czy inaczej dziękujemy ci za twój wysiłek.', 0),
